const i=[{id:"gcs-mucolytics-antitussives-001",topicId:"gcs-mucolytics-antitussives",question:"Чем являются глюкокортикостероиды по своему происхождению?",options:["Синтетическими аналогами гормонов кортизона и гидрокортизона","Продуктами жизнедеятельности плесневых грибов","Растительными экстрактами с противовоспалительным действием","Синтетическими аналогами гормонов щитовидной железы"],correctIndex:0,explanation:"Глюкокортикостероиды — это синтетические аналоги гормонов кортизона и гидрокортизона.",difficulty:"medium",tags:["ГКС","определение"]},{id:"gcs-mucolytics-antitussives-002",topicId:"gcs-mucolytics-antitussives",question:"Каким органом вырабатываются кортизон и гидрокортизон?",options:["Гипофизом","Корой надпочечников","Поджелудочной железой","Щитовидной железой"],correctIndex:1,explanation:"Кортизон и гидрокортизон вырабатываются корой надпочечников.",difficulty:"medium",tags:["ГКС","физиология"]},{id:"gcs-mucolytics-antitussives-003",topicId:"gcs-mucolytics-antitussives",question:"Какими видами действия обладают глюкокортикостероиды?",options:["Мочегонным, гипотензивным и антиаритмическим","Отхаркивающим, муколитическим и бронхорасширяющим","Гемостатическим, антикоагулянтным и ангиопротекторным","Противовоспалительным, противоаллергическим, противоотёчным и иммуноподавляющим"],correctIndex:3,explanation:"ГКС обладают сильным противовоспалительным, противоаллергическим, противоотёчным и иммуноподавляющим действием.",difficulty:"medium",tags:["ГКС","фармакология"]},{id:"gcs-mucolytics-antitussives-004",topicId:"gcs-mucolytics-antitussives",question:"Какое действие ГКС связано с подавлением иммунного ответа?",options:["Иммуноподавляющее","Противоотёчное","Противоаллергическое","Противовоспалительное"],correctIndex:0,explanation:"Глюкокортикостероиды обладают иммуноподавляющим действием наряду с противовоспалительным, противоаллергическим и противоотёчным.",difficulty:"medium",tags:["ГКС","фармакология"]},{id:"gcs-mucolytics-antitussives-005",topicId:"gcs-mucolytics-antitussives",question:"Почему глюкокортикостероиды нельзя резко отменять?",options:["Из-за риска гипертонического криза","Из-за риска надпочечниковой недостаточности","Из-за риска бронхоспазма","Из-за риска желудочного кровотечения"],correctIndex:1,explanation:"ГКС нельзя резко отменять из-за риска надпочечниковой недостаточности.",difficulty:"hard",tags:["ГКС","безопасность"]},{id:"gcs-mucolytics-antitussives-006",topicId:"gcs-mucolytics-antitussives",question:"Какое состояние может развиться при резкой отмене глюкокортикостероидов?",options:["Анафилактический шок","Тромбоэмболия лёгочной артерии","Надпочечниковая недостаточность","Острая почечная недостаточность"],correctIndex:2,explanation:"Резкая отмена ГКС несёт риск развития надпочечниковой недостаточности.",difficulty:"medium",tags:["ГКС","безопасность"]},{id:"gcs-mucolytics-antitussives-007",topicId:"gcs-mucolytics-antitussives",question:"Какие побочные эффекты могут вызывать ГКС при длительном приёме?",options:["Анемию, лейкопению и тромбоцитопению","Гипокалиемию и мышечные судороги","Тремор рук и тахикардию","Остеопороз, диабет, ожирение и гипертонию"],correctIndex:3,explanation:"При длительном приёме ГКС могут вызывать остеопороз, диабет, ожирение и гипертонию.",difficulty:"medium",tags:["ГКС","побочные эффекты"]},{id:"gcs-mucolytics-antitussives-008",topicId:"gcs-mucolytics-antitussives",question:"Какое побочное действие ГКС затрагивает костную ткань?",options:["Остеопороз","Артрит","Остеомиелит","Перелом шейки бедра как прямое следствие приёма"],correctIndex:0,explanation:"При длительном приёме глюкокортикостероидов среди побочных эффектов указан остеопороз.",difficulty:"medium",tags:["ГКС","побочные эффекты"]},{id:"gcs-mucolytics-antitussives-009",topicId:"gcs-mucolytics-antitussives",question:"Какое нарушение обмена веществ может развиться при длительном приёме ГКС?",options:["Подагра","Диабет","Фенилкетонурия","Гипотиреоз"],correctIndex:1,explanation:"Среди побочных эффектов длительного приёма ГКС указан диабет.",difficulty:"medium",tags:["ГКС","побочные эффекты"]},{id:"gcs-mucolytics-antitussives-010",topicId:"gcs-mucolytics-antitussives",question:"Какое действующее вещество относится к глюкокортикостероидам?",options:["Амброксол","Бутамират","Преднизолон","Ацетилцистеин"],correctIndex:2,explanation:"Преднизолон относится к глюкокортикостероидам; амброксол и ацетилцистеин — муколитики, бутамират — противокашлевое средство.",difficulty:"medium",tags:["ГКС","препараты"]},{id:"gcs-mucolytics-antitussives-011",topicId:"gcs-mucolytics-antitussives",question:"Какое из перечисленных веществ входит в группу глюкокортикостероидов?",options:["Бромгексин","Кодеин","Карбоцистеин","Дексаметазон"],correctIndex:3,explanation:"Дексаметазон относится к глюкокортикостероидам; бромгексин и карбоцистеин — муколитики, кодеин — противокашлевое средство.",difficulty:"medium",tags:["ГКС","препараты"]},{id:"gcs-mucolytics-antitussives-012",topicId:"gcs-mucolytics-antitussives",question:"Какое действующее вещество из группы ГКС применяется ингаляционно через небулайзер?",options:["Будесонид","Триамцинолон","Гидрокортизон","Бетаметазон"],correctIndex:0,explanation:"Будесонид — глюкокортикостероид, применяемый ингаляционно, в том числе через небулайзер.",difficulty:"medium",tags:["ГКС","препараты"]},{id:"gcs-mucolytics-antitussives-013",topicId:"gcs-mucolytics-antitussives",question:"Какое действующее вещество из таблицы ГКС является производным преднизолона?",options:["Мометазон","Метилпреднизолон","Дексаметазон","Будесонид"],correctIndex:1,explanation:"В таблице глюкокортикостероидов наряду с преднизолоном указан метилпреднизолон.",difficulty:"medium",tags:["ГКС","препараты"]},{id:"gcs-mucolytics-antitussives-014",topicId:"gcs-mucolytics-antitussives",question:"Что представляет собой кашель?",options:["Патологическую реакцию, всегда требующую подавления","Признак исключительно бактериальной инфекции","Защитный рефлекторный акт, направленный на очищение дыхательных путей","Произвольное движение, контролируемое сознанием"],correctIndex:2,explanation:"Кашель — это защитный рефлекторный акт, направленный на очищение дыхательных путей от мокроты, слизи, инородных частиц и раздражителей.",difficulty:"easy",tags:["кашель","определение"]},{id:"gcs-mucolytics-antitussives-015",topicId:"gcs-mucolytics-antitussives",question:"От чего кашель очищает дыхательные пути?",options:["Только от бактерий и вирусов","Только от избытка углекислого газа","Только от аллергенов","От мокроты, слизи, инородных частиц и раздражителей"],correctIndex:3,explanation:"Кашель направлен на очищение дыхательных путей от мокроты, слизи, инородных частиц и раздражителей.",difficulty:"easy",tags:["кашель","физиология"]},{id:"gcs-mucolytics-antitussives-016",topicId:"gcs-mucolytics-antitussives",question:"Каким центром регулируется кашлевой рефлекс?",options:["Кашлевым центром","Дыхательным центром коры головного мозга","Сосудодвигательным центром","Центром терморегуляции гипоталамуса"],correctIndex:0,explanation:"Кашлевой рефлекс регулируется кашлевым центром.",difficulty:"easy",tags:["кашель","физиология"]},{id:"gcs-mucolytics-antitussives-017",topicId:"gcs-mucolytics-antitussives",question:"Где расположен кашлевой центр?",options:["В мозжечке","В продолговатом мозге","В коре больших полушарий","В спинном мозге"],correctIndex:1,explanation:"Кашлевой центр расположен в продолговатом мозге.",difficulty:"medium",tags:["кашель","анатомия"]},{id:"gcs-mucolytics-antitussives-018",topicId:"gcs-mucolytics-antitussives",question:"Какую опасность предупреждает кашель, удаляя мокроту и загрязнения?",options:["Развитие аллергии","Повышение температуры тела","Закупорку дыхательных путей","Спазм гладкой мускулатуры бронхов"],correctIndex:2,explanation:"Кашель удаляет мокроту и загрязнения, предупреждая закупорку дыхательных путей.",difficulty:"medium",tags:["кашель","физиология"]},{id:"gcs-mucolytics-antitussives-019",topicId:"gcs-mucolytics-antitussives",question:"Чем может быть вреден длительный кашель?",options:["Он приводит к необратимому разрушению альвеол","Он вызывает стойкое повышение артериального давления","Он полностью блокирует поступление кислорода","Он нарушает сон, вызывает утомление и ухудшает качество жизни"],correctIndex:3,explanation:"Длительный кашель может нарушать сон, вызывать утомление и ухудшать качество жизни.",difficulty:"medium",tags:["кашель","клиника"]},{id:"gcs-mucolytics-antitussives-020",topicId:"gcs-mucolytics-antitussives",question:"Какое действующее вещество относится к противокашлевым средствам?",options:["Бутамират","Амброксол","Преднизолон","Бромгексин"],correctIndex:0,explanation:"Бутамират относится к противокашлевым средствам; амброксол и бромгексин — муколитики, преднизолон — ГКС.",difficulty:"medium",tags:["противокашлевые","препараты"]},{id:"gcs-mucolytics-antitussives-021",topicId:"gcs-mucolytics-antitussives",question:"Какое из перечисленных веществ является противокашлевым препаратом?",options:["Ацетилцистеин","Кодеин","Дексаметазон","Карбоцистеин"],correctIndex:1,explanation:"Кодеин относится к противокашлевым средствам; ацетилцистеин и карбоцистеин — муколитики, дексаметазон — ГКС.",difficulty:"medium",tags:["противокашлевые","препараты"]},{id:"gcs-mucolytics-antitussives-022",topicId:"gcs-mucolytics-antitussives",question:"Что такое муколитики?",options:["Средства, подавляющие кашлевой рефлекс","Средства, расширяющие просвет бронхов","Лекарственные средства, разжижающие густую вязкую мокроту","Гормональные препараты с противовоспалительным действием"],correctIndex:2,explanation:"Муколитики — это лекарственные средства, которые разжижают густую, вязкую мокроту, делая её более жидкой и лёгкой для откашливания.",difficulty:"easy",tags:["муколитики","определение"]},{id:"gcs-mucolytics-antitussives-023",topicId:"gcs-mucolytics-antitussives",question:"Какой эффект даёт разжижение мокроты муколитиками?",options:["Полное прекращение выработки слизи","Подавление кашлевого центра","Снижение температуры тела","Улучшение очищения дыхательных путей и уменьшение кашля"],correctIndex:3,explanation:"Благодаря разжижению мокроты улучшается очищение дыхательных путей и уменьшается кашель.",difficulty:"medium",tags:["муколитики","фармакология"]},{id:"gcs-mucolytics-antitussives-024",topicId:"gcs-mucolytics-antitussives",question:"Как муколитики действуют на кашлевой рефлекс?",options:["Не подавляют его, а помогают организму очистить бронхи","Полностью блокируют его на несколько часов","Усиливают его до непрерывного приступа","Действуют на него так же, как противокашлевые средства"],correctIndex:0,explanation:"Муколитики не подавляют кашлевой рефлекс, а наоборот помогают организму очистить бронхи.",difficulty:"medium",tags:["муколитики","фармакология"]},{id:"gcs-mucolytics-antitussives-025",topicId:"gcs-mucolytics-antitussives",question:"При каких заболеваниях применяются муколитики?",options:["При артериальной гипертензии и ИБС","При бронхите, трахеите, бронхопневмонии и ХОБЛ","При гастрите и язвенной болезни","При анемии и лейкозе"],correctIndex:1,explanation:"Муколитики применяются при бронхите, трахеите, бронхопневмонии и ХОБЛ.",difficulty:"medium",tags:["муколитики","показания"]},{id:"gcs-mucolytics-antitussives-026",topicId:"gcs-mucolytics-antitussives",question:"С какой группой препаратов нельзя сочетать муколитики?",options:["С бронходилататорами","С антибиотиками","С противокашлевыми препаратами","С глюкокортикостероидами"],correctIndex:2,explanation:"Муколитики нельзя сочетать с противокашлевыми препаратами (кодеин, бутамират).",difficulty:"hard",tags:["муколитики","взаимодействия"]},{id:"gcs-mucolytics-antitussives-027",topicId:"gcs-mucolytics-antitussives",question:"Чем опасно одновременное применение муколитиков и противокашлевых средств?",options:["Мокрота становится слишком густой и перекрывает бронхи","Резко снижается артериальное давление","Развивается надпочечниковая недостаточность","Мокрота разжижается, но кашель блокируется — возникает риск застоя и осложнений"],correctIndex:3,explanation:"При сочетании муколитиков с противокашлевыми препаратами мокрота разжижается, но кашель блокируется, что создаёт риск застоя и осложнений.",difficulty:"hard",tags:["муколитики","взаимодействия"]},{id:"gcs-mucolytics-antitussives-028",topicId:"gcs-mucolytics-antitussives",question:"Какие действующие вещества названы как противокашлевые, которые нельзя сочетать с муколитиками?",options:["Кодеин и бутамират","Амброксол и бромгексин","Будесонид и преднизолон","Ацетилцистеин и карбоцистеин"],correctIndex:0,explanation:"Муколитики нельзя сочетать с противокашлевыми препаратами — кодеином и бутамиратом.",difficulty:"hard",tags:["муколитики","взаимодействия"]},{id:"gcs-mucolytics-antitussives-029",topicId:"gcs-mucolytics-antitussives",question:"Какое действующее вещество относится к муколитикам?",options:["Кодеин","Амброксол","Будесонид","Бутамират"],correctIndex:1,explanation:"Амброксол относится к муколитикам; кодеин и бутамират — противокашлевые средства, будесонид — ГКС.",difficulty:"medium",tags:["муколитики","препараты"]},{id:"gcs-mucolytics-antitussives-030",topicId:"gcs-mucolytics-antitussives",question:"Какое из перечисленных веществ разжижает мокроту?",options:["Преднизолон","Мометазон","Ацетилцистеин","Метилпреднизолон"],correctIndex:2,explanation:"Ацетилцистеин относится к муколитикам, разжижающим мокроту; остальные перечисленные вещества — глюкокортикостероиды.",difficulty:"medium",tags:["муколитики","препараты"]},{id:"gcs-mucolytics-antitussives-031",topicId:"gcs-mucolytics-antitussives",question:"Какое растительное средство входит в таблицу муколитиков?",options:["Ромашка","Шалфей","Мать-и-мачеха","Алтея"],correctIndex:3,explanation:"В таблице муколитиков наряду с амброксолом, ацетилцистеином, карбоцистеином и бромгексином указана алтея.",difficulty:"medium",tags:["муколитики","препараты"]},{id:"gcs-mucolytics-antitussives-032",topicId:"gcs-mucolytics-antitussives",question:"Из приведённых веществ выберите то, которое НЕ является муколитиком.",options:["Триамцинолон","Бромгексин","Карбоцистеин","Амброксол"],correctIndex:0,explanation:"Триамцинолон — глюкокортикостероид, а бромгексин, карбоцистеин и амброксол относятся к муколитикам.",difficulty:"medium",tags:["муколитики","препараты"]},{id:"gcs-mucolytics-antitussives-033",topicId:"gcs-mucolytics-antitussives",question:"Какое свойство мокроты изменяют муколитики, облегчая её откашливание?",options:["Её цвет","Её вязкость и густоту","Её температуру","Её кислотность"],correctIndex:1,explanation:"Муколитики разжижают густую вязкую мокроту, делая её более жидкой и лёгкой для откашливания.",difficulty:"easy",tags:["муколитики","фармакология"]},{id:"gcs-mucolytics-antitussives-034",topicId:"gcs-mucolytics-antitussives",question:"Как расшифровывается аббревиатура ГКС?",options:["Гемостатические кровоостанавливающие средства","Гипотензивные комбинированные средства","Глюкокортикостероиды","Гликозидные кардиотонические средства"],correctIndex:2,explanation:"ГКС — глюкокортикостероиды, синтетические аналоги гормонов коры надпочечников.",difficulty:"easy",tags:["ГКС","терминология"]},{id:"gcs-mucolytics-antitussives-035",topicId:"gcs-mucolytics-antitussives",question:"Какое действие глюкокортикостероидов помогает уменьшить отёк тканей?",options:["Иммуноподавляющее","Противоаллергическое","Противовоспалительное","Противоотёчное"],correctIndex:3,explanation:"Среди видов действия ГКС указано противоотёчное действие.",difficulty:"medium",tags:["ГКС","фармакология"]}];export{i as default};
